Set(varShowSubmitErrors, false);
NewForm(TemplateRequestForm);
ResetForm(TemplateRequestForm)

Set(
    SubmittedRequestID,
    TemplateRequestForm.LastSubmit.ID
);

Notify(
    "Your request has been submitted successfully!",
    NotificationType.Success
);

ResetForm(TemplateRequestForm);

NewForm(TemplateRequestForm)

Set(varShowSubmitErrors, false);

Reset(TemplateServiceSubcategoryDropdown);
Reset(TemplateRequestTypeDropdown);

Set(varResetAttachments, true);
Set(varResetAttachments, false)

Set(varShowSubmitErrors, false);

Reset(TemplateRequestTypeDropdown);

Set(varResetAttachments, true);
Set(varResetAttachments, false)
